CREATE TABLE "LiveSettings" ("id" TEXT PRIMARY KEY DEFAULT 'treasure-hauls', "referralUrl" TEXT, "dailyTime" TEXT, "publishingPaused" BOOLEAN NOT NULL DEFAULT true, "bindings" JSONB NOT NULL DEFAULT '{}', "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "LiveShow" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "category" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "durationMin" INTEGER NOT NULL DEFAULT 120, "whatnotUrl" TEXT NOT NULL, "confirmedUntil" TIMESTAMP(3), "endedAt" TIMESTAMP(3), "ledger" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "LiveShow_startsAt_idx" ON "LiveShow"("startsAt");
CREATE TABLE "LiveClip" ("id" TEXT PRIMARY KEY, "showId" TEXT, "recording" TEXT NOT NULL, "startS" DOUBLE PRECISION NOT NULL, "endS" DOUBLE PRECISION NOT NULL, "title" TEXT NOT NULL, "caption" TEXT NOT NULL, "mediaUrl" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'held', "review" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "LiveClip_status_createdAt_idx" ON "LiveClip"("status","createdAt");
CREATE TABLE "LivePublication" ("id" TEXT PRIMARY KEY, "clipId" TEXT NOT NULL REFERENCES "LiveClip"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "platform" TEXT NOT NULL, "accountId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'posting', "externalId" TEXT, "url" TEXT, "error" TEXT, "attempts" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "LivePublication_clipId_platform_key" ON "LivePublication"("clipId","platform");
CREATE INDEX "LivePublication_platform_createdAt_idx" ON "LivePublication"("platform","createdAt");
